vec2 pRound(vec2 a) { return pFloor(pAdd(a, pf(0.5))); }
// a double as a pair
vec2 pOf(uvec2 d) {
  float hi = dToFloat(d);
  return vec2(hi, dToFloat(dAdd(d, dNeg(dFromFloat(hi)))));
