  vec2(1.0, 0.0), vec2(-0.5, 0.0),
  vec2(0.041666668, -1.2417635e-9), vec2(-0.0013888889, 3.3631094e-11),
  vec2(0.000024801588, -3.406996e-13), vec2(-2.755732e-7, 7.575112e-15),
