vec2 pSqrt(vec2 a) {
  if (a.x <= 0.0) return vec2(0.0);
  float x = keep(sqrt(a.x));
  vec2 r = pSub(a, twoProd(x, x));
  return quickSum(x, r.x / (2.0 * x));
