  CR[15] = fresh ? D_ONE : D_ZERO;
  CR[16] = kept ? D_ZERO : D_ONE;
  CR[17] = fresh ? D_ZERO : readDouble(a, T_CLOCK + 0);
  CR[18] = fresh ? D_ZERO : readDouble(a, T_CLOCK + 1);
  CR[19] = fresh ? D_ZERO : readDouble(a, T_CLOCK + 2);
  CR[20] = fresh ? D_ZERO : readDouble(a, T_CLOCK + 3);
  CR[22] = fresh ? dNeg(D_ONE) : readDouble(a, T_CLOCK + 4);
  CR[21] = !fresh && state(a, T_FLAGS).w != 0.0 ? D_ONE : D_ZERO;
  CR[23] = hundredths(SPEED);
  CR[24] = hundredths(EASE);
  CR[25] = dFromInt(clamp(int(floor(FPS + 0.5)), 1, 120));
  for (int pc = 0; pc < steps(80); pc++) {
    uint ins = CCODE[pc];
    uint op = ins & 31u;
    int d = int((ins >> 5) & 511u);
    uvec2 a = CR[int((ins >> 14) & 511u)], b = CR[int(ins >> 23)], r;
    if (op <= 4u) {
      // add, sub, trunc, floor, ceil: one addition, of the integer toward zero and a step where one is due
      uvec2 t = dTrunc(a);
      bool whole = op >= 2u;
      bool step = t != a && ((op == 3u && dSign(a) == 1u) || (op == 4u && dSign(a) == 0u));
      uvec2 y = whole ? (step ? (op == 3u ? dNeg(D_ONE) : D_ONE) : uvec2(0x80000000u, 0u)) : op == 1u ? dNeg(b) : b;
      r = dAdd(whole ? t : a, y);
    }
    else if (op == 5u) r = dMul(a, b);
    else if (op == 6u) r = dDiv(a, b);
    else if (op <= 9u) {
      bool less = dLt(a, b);
      r = op == 7u ? (dLt(b, a) ? b : a) : op == 8u ? (less ? b : a) : (less ? D_ONE : D_ZERO);
    }
    else r = dZero(CR[d]) ? b : a;
    CR[d] = r;
  }
  Tick k;
  k.d[0] = CR[26];
  k.d[1] = CR[27];
  k.d[2] = CR[28];
  k.d[3] = CR[29];
  k.d[4] = CR[31];
  k.draw = !dZero(CR[32]);
  k.paceSet = !dZero(CR[30]);
  k.loopT = CR[33];
  return k;
}

// The canvas's numbers, as papercut.ts works them out for a canvas of W by H pixels in doubles: texel i of the layout's
// three, as the player's floats.
vec4 layoutOf(int i) {
  uvec2 LR[30];
  for (int n = 0; n < 14; n++) LR[n] = LPOOL[n];
  LR[14] = dFromInt(int(iResolution.x));
  LR[15] = dFromInt(int(iResolution.y));
  for (int pc = 0; pc < steps(106); pc++) {
    uint ins = LCODE[pc];
    uint op = ins & 31u;
    int d = int((ins >> 5) & 511u);
    uvec2 a = LR[int((ins >> 14) & 511u)], b = LR[int(ins >> 23)], r;
    if (op <= 4u) {
      // add, sub, trunc, floor, ceil: one addition, of the integer toward zero and a step where one is due
      uvec2 t = dTrunc(a);
      bool whole = op >= 2u;
      bool step = t != a && ((op == 3u && dSign(a) == 1u) || (op == 4u && dSign(a) == 0u));
      uvec2 y = whole ? (step ? (op == 3u ? dNeg(D_ONE) : D_ONE) : uvec2(0x80000000u, 0u)) : op == 1u ? dNeg(b) : b;
      r = dAdd(whole ? t : a, y);
    }
    else if (op == 5u) r = dMul(a, b);
    else if (op == 6u) r = dDiv(a, b);
    else if (op <= 9u) {
      bool less = dLt(a, b);
      r = op == 7u ? (dLt(b, a) ? b : a) : op == 8u ? (less ? b : a) : (less ? D_ONE : D_ZERO);
    }
    else if (op == 10u) r = dZero(LR[d]) ? b : a;
    else r = dFromFloat(dToFloat(a));
    LR[d] = r;
  }
  if (i == T_CANVAS) return vec4(dToFloat(LR[16]), dToFloat(LR[23]), dToFloat(LR[24]), CONTACT);
  if (i == T_SHEET) return vec4(dToFloat(LR[17]), dToFloat(LR[18]), ALPHA.x, dToFloat(LR[19]));
  return vec4(dToFloat(LR[20]), dToFloat(LR[21]), ALPHA.y, dToFloat(LR[22]));
}

// The frame's numbers at t, the loop's seconds, as papercut.ts's papercutFrameAt works them out: texel i's, each as the
// player's float. A hill's middle and height take the sines and cosines of six angles, the light's way two, one taken
// from the other: all in one loop, so the series is written in one place.
vec4 frameOf(int i, vec2 t) {
  if (i == T_WAVES) {
    vec4 p;
    for (int j = 0; j < 4; j++) p[j] = pAdd(PHASE[j], pMul(WAVE_W[j], t)).x;
    return p;
  }
  bool light = i == T_LIGHT;
  int b = light ? 0 : i - T_BUMP;
  vec2 angle[6] = vec2[](
    light ? pMul(LOOP_W, t) : pAdd(pMul(B_WX[b], t), B_PX[b]), B_PX[b],
    pAdd(pMul(B_WY[b], t), B_PY[b]), B_PY[b],
    pAdd(pMul(B_WB[b], t), B_PB[b]), B_PB[b]
  );
  vec4 sc[6];
  for (int k = 0; k < steps(light ? 2 : 6); k++) {
    sc[k] = pSinCos(angle[k]);
    // the light's swing: a sine, so it leaves the designed light at t = 0 at its fastest and turns back at the ends
    if (light && k == 0) angle[1] = pMul(SWING, sc[0].xy);
  }
  if (light)
    return vec4(pSub(pMul(sc[1].zw, LIGHT_X), pMul(sc[1].xy, LIGHT_Y)).x, pAdd(pMul(sc[1].xy, LIGHT_X), pMul(sc[1].zw, LIGHT_Y)).x, 0.0, 0.0);
  vec2 x = pMul(pAdd(B_X[b], pMul(B_AX[b], pSub(sc[0].zw, sc[1].zw))), FRAME_HW);
  vec2 y = pMul(pAdd(B_Y[b], pMul(B_AY[b], pSub(sc[2].xy, sc[3].xy))), FRAME_HH);
  vec2 a = pMul(B_A[b], pAdd(pf(1.0), pMul(B_B[b], pSub(sc[4].xy, sc[5].xy))));
  return vec4(x.x, y.x, B_IR2[b], a.x);
}

// ==== Buffer A ==== iChannel0: Buffer A (filter: nearest, wrap: clamp)
// The state, in the first row: the mark, the settings' signature and the clock's flags, the clock's doubles, the
// canvas's shadows (kept while the canvas and the settings are), and the frame's numbers at the time drawn. Each part
// is worked out in one place (a GPU's compiler writes a function out again at each call).
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  ivec2 p = ivec2(fragCoord);
  if (p.y != 0 || p.x >= STATE) discard;
  int i = p.x;
  // the state is this text's, from an earlier frame of this run, for this canvas and these settings
  vec4 mark = state(iChannel0, T_MARK);
  bool fresh = iFrame == 0 || mark.xy != vec2(MAGIC, SCENE);
  vec2 sign = signature();
  bool kept = !fresh && mark.zw == iResolution.xy && state(iChannel0, T_FLAGS).xy == sign;
  if (i == T_MARK) fragColor = vec4(MAGIC, SCENE, iResolution.xy);
  else if (i >= T_CANVAS && i < T_WAVES) fragColor = kept ? state(iChannel0, i) : layoutOf(i);
  else {
    // every frame: the clock, and the frame's numbers at the time drawn
    Tick k = tick(iChannel0, fresh, kept);
    if (i == T_FLAGS) fragColor = vec4(sign, k.draw ? 1.0 : 0.0, k.paceSet ? 1.0 : 0.0);
    else if (i < T_CANVAS) fragColor = pieces(k.d[i - T_CLOCK]);
    else fragColor = frameOf(i, pOf(k.loopT));
  }
}

// ==== Buffer B ==== iChannel0: Buffer A (filter: nearest, wrap: clamp)
// The field: the player's field pass as it is, its uniforms from Buffer A, a texel every fourth pixel each way and one
// past each edge, in the buffer's corner; its floats kept whole, as the player's integer texture keeps their bits. Only
// in a frame the pace draws.
vec4 fragPlace;
vec2 uSize;
float uD;
vec2 uRamp;
vec4 uWarp;
vec4 uPhase;
int uBumps;
vec4 uBump[6];
uvec4 o;

vec4 field(vec2 q) {
  float s1 = uWarp.y * q.y + uPhase.x;
  float s2 = uWarp.y * q.x + uPhase.y;
  float u = uWarp.w * (q.x + q.y) + uPhase.z;
  float v = uWarp.w * (q.x - q.y) + uPhase.w;
  float su = sin(u);
  float sv = sin(v);
  vec2 w = vec2(q.x + uWarp.x * sin(s1) + uWarp.z * sv, q.y + uWarp.x * sin(s2) + uWarp.z * su);
  float c1 = uWarp.x * uWarp.y * cos(s1);
  float c2 = uWarp.x * uWarp.y * cos(s2);
  float cu = uWarp.z * uWarp.w * cos(u);
  float cv = uWarp.z * uWarp.w * cos(v);
  mat2 J = mat2(1.0 + cv, c2 + cu, c1 - cv, 1.0 + cu);
  float f = w.x * uRamp.x + w.y * uRamp.y;
  vec2 g = uRamp;
  vec3 h = vec3(0.0);
  for (int i = 0; i < 6; i++) {
    if (i >= uBumps) break;
    vec4 B = uBump[i];
    vec2 e = w - B.xy;
    float s = dot(e, e) * B.z;
    if (s < 1.0) {
      float k = 1.0 - s;
      float k2 = k * k;
      f += B.w * k2 * k;
      float c = -6.0 * B.w * k2 * B.z;
      g += c * e;
      float qq = 24.0 * B.w * B.z * B.z * k;
      h += vec3(c + qq * e.x * e.x, qq * e.x * e.y, c + qq * e.y * e.y);
    }
  }
  vec2 G = vec2(g.x * J[0][0] + g.y * J[0][1], g.x * J[1][0] + g.y * J[1][1]);
  mat2 H = mat2(h.x, h.y, h.y, h.z);
  mat2 Q = transpose(J) * H * J;
  float g2 = dot(G, G);
  float kn = g2 > 0.0 ? dot(G, Q * G) / g2 : 0.5 * (Q[0][0] + Q[1][1]);
  float tr = Q[0][0] + Q[1][1];
  float round = tr * tr > 0.0 ? clamp(8.0 * (Q[0][0] * Q[1][1] - Q[0][1] * Q[1][0]) / (tr * tr), 0.0, 1.0) : 0.0;
  return vec4(f, G, kn * round);
}
void effectMain() {
  vec2 p = (floor(fragPlace.xy) - 1.0) * 4.0 + 0.5;
  o = floatBitsToUint(field((p - 0.5 * uSize) / uD));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  ivec2 b = ivec2(fragCoord);
  // the field's texels: (W - 1) / 4 rounded up and three more, each way
  ivec2 size = (ivec2(iResolution.xy) + 2) / 4 + 3;
  if (any(greaterThanEqual(b, size)) || state(iChannel0, T_FLAGS).z == 0.0) {
    fragColor = vec4(0.0);
    return;
  }
  float one = iResolution.z;
  uSize = iResolution.xy;
  uD = state(iChannel0, T_CANVAS).x;
  uRamp = RAMP * one;
  uWarp = WARP * one;
  uPhase = state(iChannel0, T_WAVES);
  uBumps = BUMPS;
  for (int i = 0; i < 6; i++) uBump[i] = i < BUMPS ? state(iChannel0, T_BUMP + i) : vec4(0.0);
  fragPlace = vec4(fragCoord, 0.0, 1.0);
  effectMain();
  fragColor = uintBitsToFloat(o);
}

// ==== Buffer C ==== iChannel0: Buffer A (filter: nearest, wrap: clamp); iChannel1: Buffer C (filter: nearest, wrap: clamp); iChannel2: Buffer B (filter: nearest, wrap: clamp)
// The frame: the player's shading pass as it is, its uniforms from Buffer A, the field Buffer B's texels as the player
// reads its texture's (fieldBits); between the frames the pace draws, the frame drawn last.
uvec4 fieldBits(ivec2 i, int lod) { return floatBitsToUint(texelFetch(iChannel2, i, lod)); }
vec4 fragPlace;
vec2 uSize;
float uD;
vec2 uLight;
int uSheets;
vec4 uSheet[24];
float uReach[24];
vec2 uMisc;
vec4 o;

float phi(float x) {
  float t = clamp((x + 2.54) * 0.19685039, 0.0, 1.0);
  return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}

vec3 sheet(vec3 c, int k, float f, float gl, float kap, float nl, float wn, float toPx) {
  vec4 S = uSheet[k];
  float rise = uLevel[k - 1] - f;
  float d = -rise * toPx;
  float ds = d + S.y * nl;
  float size = 1.0;
  float csize = 1.0;
  if (rise > 0.0) {
    float disc = gl * gl + 2.0 * kap * rise;
    float ak = abs(kap);
    if (ak * 16.0 * S.y > gl * uD) {
      float top = gl / ak * uD;
      float R = (disc >= 0.0 ? sqrt(disc) : -sqrt(-disc)) / ak * uD;
      float e = kap < 0.0 ? 1.0 : -1.0;
      d = -e * (top - R);
      ds = -e * (sqrt(top * top - 2.0 * e * top * S.y * nl + S.y * S.y) - R);
      if (e > 0.0) {
        float R2 = max(0.0, R) * R;
        size = 1.0 - exp(-0.5 * R2 * S.x * S.x);
        csize = 1.0 - exp(-0.5 * R2 * S.w * S.w);
      }
    } else {
      d = -uD * (disc >= 0.0 ? (2.0 * rise) / (gl + sqrt(disc)) : (gl + sqrt(-disc)) / -kap);
      ds = d + S.y * nl;
    }
  }
  float x = ds * S.x;
  if (x > -2.54) c += (uShade[k] - c) * (S.z * phi(x) * size);
  float xc = d * S.w;
  if (xc > -2.54) c += (uShade[k] - c) * (uMisc.x * phi(xc) * csize);
  if (d + max(0.0, wn) > -0.5) {
    c += (uWallC[k] - c) * clamp(d + 0.5, 0.0, 1.0);
    c += (uFace[k] - c) * clamp(d + wn + 0.5, 0.0, 1.0);
  }
  return c;
}

vec4 shade(vec4 F, vec2 px) {
  float f = F.x;
  vec2 G = F.yz;
  int top = uSheets - 1;
  int b = 0;
  for (int i = 0; i < 23; i++) {
    if (i >= top) break;
    if (f >= uLevel[i]) b++;
  }
  float gl = max(1e-9, length(G));
  float toPx = uD / gl;
  float kap = F.w;
  float nl = dot(G, uLight) / gl;
  float wn = uMisc.y * nl;
  vec3 c = uFace[0];
  bool own = false;
  if (b > 0) {
    if ((f - uLevel[b - 1]) * toPx + wn >= 0.5) c = uFace[b];
    else {
      c = uFace[b - 1];
      own = true;
    }
  }
  if (own) c = sheet(c, b, f, gl, kap, nl, wn, toPx);
  if (b < top) c = sheet(c, b + 1, f, gl, kap, nl, wn, toPx);
  if (b + 1 < top && (uLevel[b + 1] - f) * toPx < uReach[b + 2]) c = sheet(c, b + 2, f, gl, kap, nl, wn, toPx);
  float a = 0.06711056 * px.x + 0.00583715 * px.y;
  float n = fract(52.9829189 * fract(a)) - 0.5;
  return vec4(c + n / 255.0, 1.0);
}
void effectMain() {
  vec2 px = vec2(fragPlace.x - 0.5, uSize.y - fragPlace.y - 0.5);
  vec2 t = px / 4.0 + 1.0;
  ivec2 i = ivec2(t);
  vec2 a = t - vec2(i);
  vec4 f00 = uintBitsToFloat(fieldBits(i, 0));
  vec4 f10 = uintBitsToFloat(fieldBits(i + ivec2(1, 0), 0));
  vec4 f01 = uintBitsToFloat(fieldBits(i + ivec2(0, 1), 0));
  vec4 f11 = uintBitsToFloat(fieldBits(i + ivec2(1, 1), 0));
  o = shade(mix(mix(f00, f10, a.x), mix(f01, f11, a.x), a.y), px);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  // without 32-bit float buffers the state cannot hold its numbers, nor a canvas narrower than its first row: magenta
  // says so
  if (iResolution.x < float(STATE) || state(iChannel0, T_MARK).x != MAGIC) {
    fragColor = vec4(1.0, 0.0, 1.0, 1.0);
    return;
  }
  if (state(iChannel0, T_FLAGS).z == 0.0) {
    fragColor = texelFetch(iChannel1, ivec2(fragCoord), 0);
    return;
  }
  vec4 canvas = state(iChannel0, T_CANVAS);
  vec4 thin = state(iChannel0, T_SHEET);
  vec4 thick = state(iChannel0, T_SHEET + 1);
  uSize = iResolution.xy;
  uD = canvas.x;
  uLight = state(iChannel0, T_LIGHT).xy;
  uSheets = SHEETS;
  for (int k = 0; k < 24; k++) {
    vec4 s = INDEX > 0 && k % INDEX == 0 ? thick : thin;
    uSheet[k] = vec4(s.xyz, canvas.y);
    uReach[k] = s.w;
  }
  uMisc = canvas.wz;
  fragPlace = vec4(fragCoord, 0.0, 1.0);
  effectMain();
  fragColor = o;
}

// ==== Image ==== iChannel0: Buffer C (filter: nearest, wrap: clamp)
// The frame on the canvas.
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  fragColor = vec4(texelFetch(iChannel0, ivec2(fragCoord), 0).rgb, 1.0);
}

